// Work out whether we got a transcript (file or pasted) or audio
const item = $input.first();
const f = item.json;
const bins = item.binary || {};
let transcriptRaw = String(f['Or Paste Transcript'] || '').trim();
let audio = null;

for (const [key, b] of Object.entries(bins)) {
  const name = String(b.fileName || '').toLowerCase();
  const mime = String(b.mimeType || '');
  if (/\.(srt|vtt|txt)$/.test(name) || mime.startsWith('text/')) {
    if (!transcriptRaw) transcriptRaw = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf8');
  } else if (mime.startsWith('audio/') || mime.startsWith('video/') || /\.(mp3|m4a|wav|mp4|mpeg|mpga|webm|ogg)$/.test(name)) {
    audio = b;
  }
}
if (!transcriptRaw && !audio) throw new Error('Please upload a transcript (SRT, VTT, TXT), paste one, or upload the audio file.');

const out = {
  json: {
    episodeTitle: f['Episode Title'] || 'Untitled episode',
    guestName: f['Guest Name'] || '',
    episodeUrl: f['Episode URL'] || '',
    keywords: f['Target Keywords'] || '',
    submitterEmail: f['Your Email'] || '',
    hasTranscript: !!transcriptRaw,
    transcriptRaw,
  },
};
if (!transcriptRaw && audio) out.binary = { audio };
return [out];

// Turn SRT / VTT (or plain text) into [mm:ss] lines
const raw = String($input.first().json.transcriptRaw || '');
const fmt = t => {
  const m = t.match(/(?:(\d{1,2}):)?(\d{1,2}):(\d{2})/);
  if (!m) return null;
  const h = Number(m[1] || 0), mm = m[2].padStart(2, '0'), ss = m[3];
  return h ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
};
const out = [];
let ts = null;
for (const line of raw.split(/\r?\n/)) {
  const t = line.trim();
  if (!t || t === 'WEBVTT' || /^\d+$/.test(t) || /^(NOTE|STYLE|Kind:|Language:)/.test(t)) continue;
  if (t.includes('-->')) { ts = fmt(t.split('-->')[0]); continue; }
  const clean = t.replace(/<[^>]+>/g, '');
  if (out.length && out[out.length - 1].endsWith(clean)) continue;
  out.push(ts ? `[${ts}] ${clean}` : clean);
  ts = null;
}
return [{ json: { transcript: out.join('\n') } }];

// Whisper verbose_json segments -> [mm:ss] lines
const segs = $input.first().json.segments || [];
const fmt = s => {
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = Math.floor(s % 60);
  const mm = String(m).padStart(2, '0'), ss = String(sec).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
};
const transcript = segs.length
  ? segs.map(s => `[${fmt(s.start)}] ${String(s.text).trim()}`).join('\n')
  : String($input.first().json.text || '');
return [{ json: { transcript } }];

