// Lay out all assets as Notion blocks and number them
const ep = $('Set Show Settings').first().json;
const a = $('Generate Clips & Quote Briefs').first().json.message.content || {};
const b = $('Write Newsletter & Show Notes').first().json.message.content || {};
const c = $('Write Social Assets').first().json.message.content || {};
const clips = a.clips || [], quotes = a.quotes || [];
const nl = b.newsletter || {}, sn = b.showNotes || {};
const slides = (c.carousel && c.carousel.slides) || [], thread = c.xThread || [];

const cut = s => String(s ?? '').slice(0, 1900);
const txt = (content, bold = false) => ({ type: 'text', text: { content: cut(content) }, annotations: { bold } });
const block = (type, rich, extra = {}) => ({ object: 'block', type, [type]: { rich_text: rich, ...extra } });
const para = s => {
  const str = String(s ?? '');
  const parts = [];
  for (let i = 0; i < str.length; i += 1900) parts.push(str.slice(i, i + 1900));
  return (parts.length ? parts : ['']).map(p => block('paragraph', [txt(p)]));
};
const body = s => String(s || '').split(/\n{2,}/).map(x => x.trim()).filter(Boolean).flatMap(para);
const label = (l, v) => block('paragraph', [txt(`${l}: `, true), txt(v)]);
const h = (lvl, t) => block(`heading_${lvl}`, [txt(t)]);
const bullet = t => block('bulleted_list_item', [txt(t)]);
const numbered = (bold, rest) => block('numbered_list_item', bold ? [txt(bold, true), txt(rest)] : [txt(rest)]);
const divider = { object: 'block', type: 'divider', divider: {} };

let n = 0;
const blocks = [
  block('callout', [txt('Review each asset below. When done, set Status to Approved, or to Changes Requested and add notes in Review Notes.')],
        { icon: { type: 'emoji', emoji: '📝' } }),
];
if (ep.episodeUrl) blocks.push(label('Episode link', ep.episodeUrl));

blocks.push(h(2, `Short-form clips (${clips.length})`));
for (const cl of clips) {
  n++;
  blocks.push(h(3, `Asset ${n}: ${cl.title}`), label('Timestamps', `${cl.start} - ${cl.end}`),
    label('On-screen hook', cl.hook), label('Why it works', cl.whyItWorks), label('Best platform', cl.bestPlatform));
}
blocks.push(divider);

n++;
blocks.push(h(2, `Asset ${n}: Newsletter`), label('Subject options', (nl.subjectLines || []).join('  |  ')),
  label('Preview text', nl.previewText), ...body(nl.body), divider);

n++;
blocks.push(h(2, `Asset ${n}: SEO show notes`), label('SEO title', sn.seoTitle), label('Meta description', sn.metaDescription),
  label('Slug', sn.slug), ...body(sn.summary),
  h(3, 'Chapters'), ...(sn.chapters || []).map(ch => bullet(`${ch.time} - ${ch.title}`)),
  h(3, 'Key takeaways'), ...(sn.keyTakeaways || []).map(bullet));
if ((sn.resourcesMentioned || []).length) blocks.push(h(3, 'Resources mentioned'), ...sn.resourcesMentioned.map(bullet));
blocks.push(label('Keywords', (sn.keywords || []).join(', ')), divider);

n++;
blocks.push(h(2, `Asset ${n}: LinkedIn carousel (${slides.length} slides)`),
  ...slides.map(s => numbered(`${s.headline}: `, s.body)), divider);

n++;
blocks.push(h(2, `Asset ${n}: LinkedIn post`), ...body(c.linkedinPost), divider);

n++;
blocks.push(h(2, `Asset ${n}: X thread (${thread.length} posts)`), ...thread.map(t => numbered('', t)), divider);

blocks.push(h(2, `Quote graphic briefs (${quotes.length})`));
for (const q of quotes) {
  n++;
  blocks.push(h(3, `Asset ${n}: Quote graphic`), block('quote', [txt(q.quote)]),
    label('Speaker', q.speaker), label('Timestamp', q.timestamp), label('Layout', q.layout),
    label('Colour mood', q.colorMood), label('Image idea', q.imageIdea), label('Designer note', q.designerNote));
}

const batches = [];
for (let i = 0; i < blocks.length; i += 90) batches.push(blocks.slice(i, i + 90));

return [{
  json: {
    title: `${ep.episodeTitle} - content pack`,
    guestName: ep.guestName,
    submitterEmail: ep.submitterEmail,
    assetCount: n,
    batches,
  },
}];

// One item per block batch so Notion's 100-block limit is respected
const pageId = $input.first().json.id;
const { batches } = $('Package 15 Assets').first().json;
return batches.map(children => ({ json: { pageId, children } }));
